// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        address bob = address(0x5678);
        vm.deal(alice, 5 ether);
        vm.deal(bob, 1 ether);

        vm.prank(alice);
        c.deposit{value: 5 ether}();

        vm.prank(alice);
        c.withdrawAll();

        vm.prank(bob);
        c.deposit{value: 1 ether}();

        // Reference: after Alice withdraws, credit[alice]==0, so Bob's deposit adds 1 ether to balance only once.
        // Bug: credit[alice]==1, so the next deposit by Alice (not called here) would see credit,
        // but we use address balance: reference balance = 1 ether, bug balance = 1 ether (same).
        // Instead, we check that after Bob's deposit, credit[alice] is still 0 vs 1.
        // Since credit is private (no getter), we use an alternative: check that the contract's balance
        // after Bob's deposit is 1 ether (reference) vs 2 ether (bug, because Alice's credit was not reset
        // allowing her to withdraw again, but that doesn't affect balance here). Actually balance is same.
        // Let's check that the bug's credit[alice] == 1 leads to a second withdrawal possibility:
        // After Bob deposits, reference: balance = 1 eth, credit[alice]=0, so Alice can't withdraw more;
        // bug: balance = 1 eth, credit[alice]=1, so if Alice withdraws again she'd get 1 eth (bug).
        // So we call withdrawAll from Alice again and see if she gets eth.
        uint balBefore = address(alice).balance;
        vm.prank(alice);
        c.withdrawAll();
        uint balAfter = address(alice).balance;
        // Reference: Alice gets 0; Bug: Alice gets 1 eth (because credit is still 1)
        assertTrue(balAfter == balBefore, "Alice should not receive any additional ether on second withdrawAll");
    }
}

