pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.deposit{value: 1 ether}();
        vm.prank(alice);
        c.withdrawAll();
        // First withdrawal succeeds; reference sets credit to 0, bug doesn't.
        vm.prank(alice);
        // Second withdrawal on buggy contract reverts due to balance underflow (since credit still 1 ether but balance is 0).
        // On reference, second withdrawal does nothing because credit is 0.
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        // Reference passes (ok == true) because no revert. Bug fails (ok == false).
        assertTrue(ok);
    }
}

